import csv
import yaml
from acc_system import AdaptiveCruiseControl
from evaluate import evaluate

def tune():
    best_params = None
    min_score = float('inf')

    for kp_s in [0.4, 0.5, 0.6]:
        for ki_s in [0.01, 0.05]:
            for kp_d in [0.4, 0.6, 0.8]:
                for ki_d in [0.01, 0.05]:
                    p_speed = {'kp': kp_s, 'ki': ki_s, 'kd': 0.1}
                    p_dist = {'kp': kp_d, 'ki': ki_d, 'kd': 0.2}
                    try:
                        m = evaluate(p_speed, p_dist)
                        if m['min_dist'] < 5: continue
                        if m['rise_time'] is None or m['rise_time'] > 10: continue
                        if m['overshoot'] > 5: continue

                        # Use ss_dist_error as the score to minimize
                        score = m['ss_dist_error'] if m['ss_dist_error'] is not None else 100
                        if score < min_score:
                            min_score = score
                            best_params = (p_speed, p_dist, m)
                    except:
                        continue

    return best_params

if __name__ == "__main__":
    best = tune()
    print(best)

import csv
import yaml
from acc_system import AdaptiveCruiseControl
from evaluate import evaluate

def tune():
    best_params = None
    max_min_dist = -100

    for kp_s in [0.5, 0.7, 1.0]:
        for kd_s in [0.0, 0.5]:
            for kp_d in [0.2, 0.5, 1.0]:
                for kd_d in [1.0, 2.0, 4.0]:
                    p_speed = {'kp': kp_s, 'ki': 0.01, 'kd': kd_s}
                    p_dist = {'kp': kp_d, 'ki': 0.01, 'kd': kd_d}
                    m = evaluate(p_speed, p_dist)

                    if m['rise_time'] and m['rise_time'] <= 10.5 and m['overshoot'] <= 10:
                        if m['min_dist'] > max_min_dist:
                            max_min_dist = m['min_dist']
                            best_params = (p_speed, p_dist, m)
                            print(f"New best: {best_params}")

    return best_params

if __name__ == "__main__":
    best = tune()
    print("Final best:", best)

